import { cn } from "@/registry/luma/lib/utils";

function AspectRatio({
  ratio,
  className,
  ...props
}: React.ComponentProps<"div"> & { ratio: number }) {
  return (
    <div
      data-slot="aspect-ratio"
      style={
        {
          "--ratio": ratio,
        } as React.CSSProperties
      }
      className={cn(
        "relative aspect-(--ratio) w-full [&>*]:absolute [&>*]:inset-0 [&>*]:size-full [&>img]:rounded-[inherit]",
        className,
      )}
      {...props}
    />
  );
}

export { AspectRatio };
